SELECT MIN((efficiency_profile->'degradation'->>'cumdegpct')::numeric), 
       MAX((efficiency_profile->'degradation'->>'cumdegpct')::numeric)
FROM performance;

-- Check all keys in degradation and current_efficiency
SELECT DISTINCT jsonb_object_keys(efficiency_profile->'degradation') FROM performance;
SELECT DISTINCT jsonb_object_keys(efficiency_profile->'current_efficiency') FROM performance;

SELECT MIN((efficiency_profile->'current_efficiency'->>'efflosspct')::numeric), 
       MAX((efficiency_profile->'current_efficiency'->>'efflosspct')::numeric)
FROM performance;

-- Check the relationship between maintenance and panels/plants
SELECT m.maintregistry, m.wtyclaimcnt, m.compref, m.powerref 
FROM maintenance m LIMIT 5;

-- Check how many panels have maintenance records
SELECT COUNT(DISTINCT p.panemark) FROM panel p;
SELECT COUNT(DISTINCT m.compref) FROM maintenance m;

-- Check if None is actually NULL or a string
SELECT COUNT(*) FROM maintenance WHERE wtyclaimcnt IS NULL;
SELECT COUNT(*) FROM maintenance WHERE wtyclaimcnt = 0;

